// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CmsPage) predicate.CmsPage {
	return predicate.CmsPage(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CmsPage) predicate.CmsPage {
	return predicate.CmsPage(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CmsPage) predicate.CmsPage {
	return predicate.CmsPage(sql.NotPredicates(p))
}
